// Byte-level helpers. Bytes are represented as plain arrays of integers (0-255),
// mirroring Python's immutable `bytes` objects without relying on any
// platform-specific binary container.

// Encode a JS string to a byte array using UTF-8, exactly like Python's
// str.encode() (which defaults to UTF-8).
export function utf8Encode(str) {
  const out = [];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return out;
}

// Convert a pure-ASCII string into a byte array (one byte per character).
export function asciiToBytes(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) out.push(str.charCodeAt(i) & 0x7f);
  return out;
}

