// Re-implementation of the Python `base58` package's public behaviour
// (Bitcoin alphabet) using manual BigInt arithmetic.
//
// Byte strings are represented as arrays of integers (0-255); encoded
// results are plain ASCII strings.

import { sha256 } from './sha256.mjs';

const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const INDEXES = new Map();
for (let i = 0; i < ALPHABET.length; i++) INDEXES.set(ALPHABET[i], i);

function bytesToBigInt(bytes) {
  let v = 0n;
  for (const b of bytes) v = (v << 8n) | BigInt(b);
  return v;
}

function bigIntToBytes(v) {
  const out = [];
  while (v > 0n) {
    out.unshift(Number(v & 0xffn));
    v >>= 8n;
  }
  return out;
}

// base58.b58encode(bytes) -> encoded ASCII string
export function b58encode(bytes) {
  let zeros = 0;
  while (zeros < bytes.length && bytes[zeros] === 0) zeros++;

  let v = bytesToBigInt(bytes);
  let encoded = '';
  while (v > 0n) {
    encoded = ALPHABET[Number(v % 58n)] + encoded;
    v /= 58n;
  }
  return '1'.repeat(zeros) + encoded;
}

// base58.b58decode(str) -> byte array
export function b58decode(str) {
  let zeros = 0;
  while (zeros < str.length && str[zeros] === '1') zeros++;

  let v = 0n;
  for (const ch of str) {
    const idx = INDEXES.get(ch);
    if (idx === undefined) {
      throw new Error(`Invalid character '${ch}'`);
    }
    v = v * 58n + BigInt(idx);
  }
  return new Array(zeros).fill(0).concat(bigIntToBytes(v));
}

// base58.b58encode_int(int) -> encoded ASCII string (no leading-zero handling)
export function b58encode_int(value) {
  let v = BigInt(value);
  if (v === 0n) return ALPHABET[0];
  if (v < 0n) throw new Error("Can't encode negative numbers");
  let encoded = '';
  while (v > 0n) {
    encoded = ALPHABET[Number(v % 58n)] + encoded;
    v /= 58n;
  }
  return encoded;
}

// base58.b58decode_int(str) -> BigInt
export function b58decode_int(str) {
  let v = 0n;
  for (const ch of str) {
    const idx = INDEXES.get(ch);
    if (idx === undefined) {
      throw new Error(`Invalid character '${ch}'`);
    }
    v = v * 58n + BigInt(idx);
  }
  return v;
}

function checksum(payload) {
  return sha256(sha256(payload)).slice(0, 4);
}

// base58.b58encode_check(bytes) -> encoded ASCII string with 4-byte checksum
export function b58encode_check(payload) {
  return b58encode(payload.concat(checksum(payload)));
}

// base58.b58decode_check(str) -> byte array (checksum verified & stripped)
export function b58decode_check(str) {
  const data = b58decode(str);
  const payload = data.slice(0, data.length - 4);
  const actual = data.slice(data.length - 4);
  const expected = checksum(payload);
  for (let i = 0; i < 4; i++) {
    if (actual[i] !== expected[i]) throw new Error('Invalid checksum');
  }
  return payload;
}

